from __future__ import annotations

Pattern2D = list[list[bool]]

def _tm(g: Pattern2D) -> bool:
    p, q = len(g), len(g[0])
    return all(g[(-t) % p][v] == g[t][v] for t in range(p) for v in range(q))

def _pm(g: Pattern2D) -> bool:
    p, q = len(g), len(g[0])
    return all(g[t][(-v) % q] == g[t][v] for t in range(p) for v in range(q))

def _r2(g: Pattern2D) -> bool:
    p, q = len(g), len(g[0])
    return all(g[(-t) % p][(-v) % q] == g[t][v] for t in range(p) for v in range(q))

def classify(g: Pattern2D) -> str:
    tm, pm, r2 = _tm(g), _pm(g), _r2(g)
    if tm and pm:
        return 'pmm (bilateral palindrome) -- contains p2 rotation'
    if r2:
        return 'p2 (call-and-response)'
    if tm or pm:
        return 'pm (palindrome)'
    return 'p1 (free rhythm)'

if __name__ == '__main__':
    grids = {
        'free':   [[True, False, False, True], [False, True, False, False]],
        'p2':     [[True, False, False, False], [False, False, False, True]],
        'pmm':    [[True, False, False, True], [True, False, False, True]],
    }
    for name, g in grids.items():
        print(f'{name:6} -> {classify(g)}')

