function TRANSLATION_SYM_GROUP(r, p):
    G <- empty list
    for k in 0 .. p-1:
        is_sym <- true
        for n in 0 .. p-1:
            if r[(n + k) mod p] != r[n]:
                is_sym <- false; break
        if is_sym:
            append k to G
    return G    # always a subgroup of Z/pZ; |G| divides p

